import Foundation
import RealityKit

// MARK: - Generic 3D wardrobe: per-item asset + per-character fit table + data-driven equip effects
//
// Data contract (bundled as `moliboo_wardrobe_fits.json`; generated by the wardrobe pipeline, see
// docs/moliboo/WARDROBE_FIT_TABLE.md). Until it ships, the table is empty and only manifest cosmetics
// (the Signature Cap) render in 3D. Nothing here reloads the character: items attach to its anchors.

enum MolibooEquipEffect: String, Codable, CaseIterable, Sendable {
    case none, popIn = "pop_in", sparkle, bounce, shimmer
}

struct MolibooEquipEffectSpec: Codable, Equatable, Sendable {
    var effect: MolibooEquipEffect
    var duration: Double = 0.35
    var overshoot: Float = 1.15      // peak scale multiplier for pop/bounce/sparkle
    var pulses: Int = 2              // shimmer / bounce repetitions
    static let `default` = MolibooEquipEffectSpec(effect: .popIn)
}

struct MolibooWardrobeItemAsset: Codable, Equatable, Sendable {
    var asset: String                       // USDZ base name in the bundle
    var slot: String                        // MascotWardrobeSlot rawValue
    var variants: [String: String]? = nil   // variant name → asset (e.g. "wide" for Moss, "tall" for Bolt)
    var effect: MolibooEquipEffectSpec? = nil
}

struct MolibooWardrobeFit: Codable, Equatable, Sendable {
    var anchor: String                      // anchor entity name on the character, e.g. "Pip_Anchor_Head"
    var offset: [Float] = [0, 0, 0]
    var rotationDegrees: [Float] = [0, 0, 0]
    var scale: Float = 1
    var variant: String? = nil
    var hidden: Bool = false                // explicit "doesn't fit this character"
}

struct MolibooWardrobeFitTable: Codable, Equatable, Sendable {
    var version: Int = 1
    var items: [String: MolibooWardrobeItemAsset] = [:]
    /// characterID → key → fit. Key is an item id, or "slot:<slot>" as the per-slot default.
    var fits: [String: [String: MolibooWardrobeFit]] = [:]
    /// Per-slot default effect when an item has none.
    var slotEffects: [String: MolibooEquipEffectSpec] = [:]

    static let empty = MolibooWardrobeFitTable()
    static let resourceName = "moliboo_wardrobe_fits"

    static func bundled(_ bundle: Bundle = .main) -> MolibooWardrobeFitTable {
        guard let url = bundle.url(forResource: resourceName, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let t = try? JSONDecoder().decode(MolibooWardrobeFitTable.self, from: data) else { return .empty }
        return t
    }

    struct Resolved: Equatable, Sendable {
        let itemID: String
        let asset: String
        let fit: MolibooWardrobeFit
        let effect: MolibooEquipEffectSpec
    }

    /// Item fit for a character: item-specific entry wins, then the slot default. nil = not available in 3D.
    func resolve(itemID: String, characterID: String) -> Resolved? {
        guard let item = items[itemID], let table = fits[characterID],
              let fit = table[itemID] ?? table["slot:\(item.slot)"], !fit.hidden else { return nil }
        let asset = fit.variant.flatMap { item.variants?[$0] } ?? item.asset
        let effect = item.effect ?? slotEffects[item.slot] ?? .default
        return Resolved(itemID: itemID, asset: asset, fit: fit, effect: effect)
    }

    func supportedItemIDs(for characterID: String) -> Set<String> {
        Set(items.keys.filter { resolve(itemID: $0, characterID: characterID) != nil })
    }
}

/// Where wardrobe item USDZs live. Free/earnable items ship in the app (`MolibooWardrobe/`); premium items are an
/// On-Demand Resources pack (`MolibooWardrobePremium/`, tag `moliboo.wardrobe.premium`) fetched on first use, so they
/// don't count against the initial download. Debug/simulator builds serve the pack locally.
@MainActor
enum MolibooWardrobeAssets {
    static let bundledFolder = "MolibooWardrobe"
    static let premiumFolder = "MolibooWardrobePremium"
    static let premiumTag = "moliboo.wardrobe.premium"
    enum LoadError: Error { case missing(String) }
    private static var premiumRequest: NSBundleResourceRequest?
    private static var premiumTask: Task<Bool, Never>?
    private(set) static var premiumAvailable = false

    static func url(for asset: String, bundle: Bundle = .main) -> URL? {
        bundle.url(forResource: asset, withExtension: "usdz", subdirectory: bundledFolder)
            ?? bundle.url(forResource: asset, withExtension: "usdz", subdirectory: premiumFolder)
            ?? bundle.url(forResource: asset, withExtension: "usdz")
    }

    /// Begins (once) and keeps access to the premium pack for the app's lifetime.
    @discardableResult
    static func ensurePremium() async -> Bool {
        if premiumAvailable { return true }
        // NSBundleResourceRequest may only be begun once: concurrent loads (several wardrobe items at Studio open)
        // used to each call (conditionally)beginAccessing on the shared request, which throws
        // NSInvalidArgumentException "beginAccessingResources was called more than once" on device (MOL device crash).
        // All callers now await one shared task; a failed attempt clears it so a later call retries with a fresh request.
        if let t = premiumTask { return await t.value }
        let t = Task { @MainActor () -> Bool in
            let r = NSBundleResourceRequest(tags: [premiumTag])
            r.loadingPriority = NSBundleResourceRequestLoadingPriorityUrgent
            premiumRequest = r
            if await r.conditionallyBeginAccessingResources() { return true }
            do { try await r.beginAccessingResources(); return true } catch { return false }
        }
        premiumTask = t
        let ok = await t.value
        premiumAvailable = ok
        if !ok { premiumTask = nil; premiumRequest = nil }
        return ok
    }

    static func load(_ asset: String) async throws -> Entity {
        if url(for: asset) == nil { await ensurePremium() }
        guard let u = url(for: asset) ?? premiumRequest?.bundle.url(forResource: asset, withExtension: "usdz", subdirectory: premiumFolder)
        else { throw LoadError.missing(asset) }
        return try await Entity(contentsOf: u)
    }
}

/// Small LRU of loaded item templates; equips get `clone(recursive:)`. Concurrent requests share one load.
@MainActor
final class MolibooWardrobeAssetCache {
    typealias Loader = @MainActor (String) async throws -> Entity
    let capacity: Int
    private let loader: Loader
    private var templates: [String: Entity] = [:]
    private var order: [String] = []
    private var inFlight: [String: Task<Entity, Error>] = [:]
    private(set) var loads = 0

    init(capacity: Int = 6, loader: @escaping Loader = { try await MolibooWardrobeAssets.load($0) }) {
        self.capacity = capacity
        self.loader = loader
    }

    var cachedAssets: [String] { order }

    func instance(_ asset: String) async throws -> Entity {
        if let t = templates[asset] { touch(asset); return t.clone(recursive: true) }
        if let task = inFlight[asset] { return try await task.value.clone(recursive: true) }
        let task = Task { @MainActor in try await loader(asset) }
        inFlight[asset] = task
        defer { inFlight[asset] = nil }
        let t = try await task.value
        loads += 1
        templates[asset] = t
        touch(asset)
        while order.count > capacity { templates.removeValue(forKey: order.removeFirst()) }
        return t.clone(recursive: true)
    }

    func purge() { templates.removeAll(); order.removeAll() }

    private func touch(_ a: String) { order.removeAll { $0 == a }; order.append(a) }
}

/// Attaches fit-table items to a loaded character's anchors (lazily, never reloading the character) and plays the
/// item's equip effect. Manifest cosmetics (the Signature Cap) stay with `MolibooSceneController.equip`.
@MainActor @Observable
final class MolibooWardrobeRig {
    let characterID: String
    let table: MolibooWardrobeFitTable
    @ObservationIgnored private let anchor: (String) -> Entity?
    @ObservationIgnored let cache: MolibooWardrobeAssetCache
    private(set) var equipped: [String: Entity] = [:]
    private(set) var lastEffect: MolibooEquipEffect = .none
    var reduceMotion = false
    @ObservationIgnored private var stopped = false

    init(characterID: String, table: MolibooWardrobeFitTable, cache: MolibooWardrobeAssetCache = .init(), anchor: @escaping (String) -> Entity?) {
        self.characterID = characterID
        self.table = table
        self.cache = cache
        self.anchor = anchor
    }

    convenience init(controller: MolibooSceneController, table: MolibooWardrobeFitTable = .bundled()) {
        self.init(characterID: controller.descriptor.id, table: table) { [weak controller] in controller?.anchor($0) }
    }

    func supports(_ itemID: String) -> Bool { table.resolve(itemID: itemID, characterID: characterID) != nil }

    func sync(_ ids: [String]) async {
        let wanted = Set(ids.filter(supports))
        for id in equipped.keys where !wanted.contains(id) { unequip(id) }
        for id in wanted where equipped[id] == nil { await equip(id) }
    }

    @discardableResult
    func equip(_ itemID: String) async -> Bool {
        guard !stopped, equipped[itemID] == nil, let r = table.resolve(itemID: itemID, characterID: characterID),
              let parent = anchor(r.fit.anchor), let e = try? await cache.instance(r.asset), !stopped else { return false }
        e.name = "Wardrobe_\(itemID)"
        let rot = r.fit.rotationDegrees.map { $0 * .pi / 180 } + [0, 0, 0]
        var target = Transform.identity
        target.rotation = simd_quatf(angle: rot[2], axis: [0, 0, 1]) * simd_quatf(angle: rot[1], axis: [0, 1, 0]) * simd_quatf(angle: rot[0], axis: [1, 0, 0])
        let o = r.fit.offset + [0, 0, 0]
        target.translation = [o[0], o[1], o[2]]
        target.scale = .init(repeating: r.fit.scale)
        parent.addChild(e)
        equipped[itemID] = e
        play(reduceMotion ? .init(effect: .none) : r.effect, on: e, target: target)
        return true
    }

    func unequip(_ itemID: String) { equipped.removeValue(forKey: itemID)?.removeFromParent() }

    func stop() {
        stopped = true
        for e in equipped.values { e.stopAllAnimations(); e.removeFromParent() }
        equipped.removeAll()
    }

    /// Effects are transform-only (no particles/materials) so they're cheap and teardown-safe.
    private func play(_ spec: MolibooEquipEffectSpec, on e: Entity, target: Transform) {
        lastEffect = spec.effect
        let d = max(0.05, spec.duration)
        var peak = target; peak.scale = target.scale * spec.overshoot
        var start = target
        switch spec.effect {
        case .none:
            e.transform = target
            return
        case .popIn:
            start.scale = target.scale * 0.01
        case .bounce:
            start.translation.y += 0.02
        case .sparkle:
            start.scale = target.scale * 0.01
            start.rotation = target.rotation * simd_quatf(angle: -.pi / 2, axis: [0, 1, 0])
        case .shimmer:
            break
        }
        e.transform = start
        let steps: [Transform] = spec.effect == .shimmer || spec.effect == .bounce
            ? Array(repeating: [peak, target], count: max(1, spec.pulses)).flatMap { $0 }
            : [peak, target]
        let per = d / Double(steps.count)
        Task { @MainActor [weak e] in
            for (i, t) in steps.enumerated() {
                guard let e, e.parent != nil else { return }
                e.move(to: t, relativeTo: e.parent, duration: per, timingFunction: i == steps.count - 1 ? .easeOut : .easeIn)
                try? await Task.sleep(for: .seconds(per))
            }
        }
    }
}

// MARK: - Tolerant decoding (omitted fields take their defaults; generated tables stay terse)

extension MolibooEquipEffectSpec {
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        effect = (try? c.decode(MolibooEquipEffect.self, forKey: .effect)) ?? .popIn   // unknown effect → pop-in
        duration = try c.decodeIfPresent(Double.self, forKey: .duration) ?? 0.35
        overshoot = try c.decodeIfPresent(Float.self, forKey: .overshoot) ?? 1.15
        pulses = try c.decodeIfPresent(Int.self, forKey: .pulses) ?? 2
    }
}

extension MolibooWardrobeFit {
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        anchor = try c.decode(String.self, forKey: .anchor)
        offset = try c.decodeIfPresent([Float].self, forKey: .offset) ?? [0, 0, 0]
        rotationDegrees = try c.decodeIfPresent([Float].self, forKey: .rotationDegrees) ?? [0, 0, 0]
        scale = try c.decodeIfPresent(Float.self, forKey: .scale) ?? 1
        variant = try c.decodeIfPresent(String.self, forKey: .variant)
        hidden = try c.decodeIfPresent(Bool.self, forKey: .hidden) ?? false
    }
}

extension MolibooWardrobeFitTable {
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        version = try c.decodeIfPresent(Int.self, forKey: .version) ?? 1
        items = try c.decodeIfPresent([String: MolibooWardrobeItemAsset].self, forKey: .items) ?? [:]
        fits = try c.decodeIfPresent([String: [String: MolibooWardrobeFit]].self, forKey: .fits) ?? [:]
        slotEffects = try c.decodeIfPresent([String: MolibooEquipEffectSpec].self, forKey: .slotEffects) ?? [:]
    }
}
